32	// 金额、费率、手续费与扣款总额的数值规则见 charge.go（与账本结算共用
33	// 同一实现）。金额或费率不合法、总额超出 int64 时一律 rejected 且不扣款、
34	// 不留结算引用、不占用编号；总额可表示但余额不足时 failed；
35	// 只有成功才标记编号。
36	func Execute(intent Intent, feeBps int, spent map[string]bool, balance int64) Settlement {
37		if intent.State != "pending" {
38			return Settlement{Intent: intent.ID, Status: "rejected", Reason: "intent is not pending"}
39		}
40		if spent[intent.ID] {
41			return Settlement{Intent: intent.ID, Status: "rejected", Reason: "duplicate settlement attempt"}
42		}
43		if !amountValid(intent.Amount) {
44			return Settlement{Intent: intent.ID, Status: "rejected", Reason: reasonBadAmount}
45		}
46		if !feeBpsValid(feeBps) {
47			return Settlement{Intent: intent.ID, Status: "rejected", Reason: reasonBadFeeBps(feeBps)}
48		}
49		_, total, ok := chargeFor(intent.Amount, feeBps)
50		if !ok {
51			return Settlement{Intent: intent.ID, Status: "rejected", Reason: reasonOverflow}
52		}
53		if total > balance {
54			return Settlement{Intent: intent.ID, Status: "failed", Reason: "insufficient balance for amount plus fee"}
55		}
56		spent[intent.ID] = true
57		return Settlement{Intent: intent.ID, Charged: total, FeeBps: feeBps, Ref: "settle:" + intent.ID, Status: "settled"}
58	}
59	
