206			// 失败的真实 p2 不能被当成已结算：预览里它是首次“预计成功”，
207			// 预计成功序号为 2；预览不继承真实 p2 的 storage_error。
208			p2Prev := prevRes.Results[1]
209			if p2Prev.Status != StatusSettled {
210				t.Fatalf("preview p2 must be predicted settled, got %+v", p2Prev)
211			}
212			assertRecord(t, "preview p2 predicted record", p2Prev.Record, wantP2)
213		} else {
214			// 两笔都成功：预览里 p2 也是 duplicate，携带真实 p2 的原结算记录（序号 2）。
215			p2Prev := prevRes.Results[1]
216			if p2Prev.Status != StatusDuplicate || p2Prev.Reason != reasonDuplicate {
217				t.Fatalf("preview p2: %+v", p2Prev)
218			}
219			assertRecord(t, "preview p2 duplicate record", p2Prev.Record, wantP2)
220		}
221		// p3 两种结局下都是余额不足，且失败项不携带任何记录。
222		if r := prevRes.Results[2]; r.Status != StatusFunds || r.Record != nil {
223			t.Fatalf("preview p3: %+v", r)
224		}
225		for i, r := range prevRes.Results {
226			if r.Status == StatusStorage {
227				t.Fatalf("preview must never report storage_error, item %d: %+v", i, r)
228			}
229		}
230	
231		// ---- 预览不写账本：预览结束后的余额与历史只等于“真实批次自身完成后” ----
232		snap := mustQuery(t, lPreview)
233		if len(snap.Refunds) != 0 {
234			t.Fatalf("unexpected refunds: %+v", snap.Refunds)
235		}
236		if len(snap.Settlements) != len(wantRealRecords) ||
237			!reflect.DeepEqual(snap.Settlements, wantRealRecords) {
238			t.Fatalf("history after preview:\n got %+v\nwant %+v (predicted p2/p3 must not be persisted, no seq reserved)",
239				snap.Settlements, wantRealRecords)
240		}
241		if bal, _ := lPreview.Balance(acct, asset); bal != wantBalanceAfterBatch {
242			t.Fatalf("balance after preview=%d want %d (preview must not charge)", bal, wantBalanceAfterBatch)
243		}
244	
245		// 账本文件同样只反映真实批次：关闭全部句柄使注册表项注销，重新从磁盘打开。
246		lSubmit.Close()
247		lPreview.Close()
248		fromDisk := openOrFail(t, path)
249		diskSnap := mustQuery(t, fromDisk)
250		if !reflect.DeepEqual(diskSnap.Settlements, wantRealRecords) {
251			t.Fatalf("ledger file after preview:\n got %+v\nwant %+v", diskSnap.Settlements, wantRealRecords)
252		}
253		if bal, _ := fromDisk.Balance(acct, asset); bal != wantBalanceAfterBatch {
254			t.Fatalf("ledger file balance=%d want %d", bal, wantBalanceAfterBatch)
255		}
256	
257		// ---- 预览不预留编号/序号：失败的真实 p2 仍可真实提交成功，不变成 duplicate ----
258		if failSecond {
259			// p2 之前只是“保存失败”，预览里又“预计成功”过；二者都不能占用编号：
260			// 现在真实提交 p2 必须 settled（而非 duplicate），成功序号 2，余额 40→10。
261			res, err := fromDisk.Submit(FeeBatch{FeeBps: 0, Intents: []PaymentIntent{
262				intent("p2", acct, asset, p2Amount),
263			}})
264			if err != nil {
265				t.Fatalf("resubmit p2: %v", err)
266			}
267			if r := res.Results[0]; r.Status != StatusSettled {
268				t.Fatalf("storage-failed p2 must settle for real on retry, got %+v", r)
269			}
270			assertRecord(t, "resubmitted p2", res.Results[0].Record, wantP2)
271		} else {
272			// 两笔都已成功：p2 原样重复提交仍 duplicate、携带原记录、不再扣款。
273			res, err := fromDisk.Submit(FeeBatch{FeeBps: 0, Intents: []PaymentIntent{
274				intent("p2", acct, asset, p2Amount),
275			}})
276			if err != nil {
277				t.Fatalf("repeat p2: %v", err)
278			}
279			if r := res.Results[0]; r.Status != StatusDuplicate {
280				t.Fatalf("settled p2 repeat must be duplicate, got %+v", r)
281			}
282			assertRecord(t, "repeat p2 original record", res.Results[0].Record, wantP2)
283		}
284	
285		// 此刻两种结局收敛到同一状态：余额 10。预览里“预计余额不足”的 p3 从未预留，
286		// 真实提交 p3=15 依旧因 10<15 而余额不足，且不留记录、序号仍停在 2。
287		p3, err := fromDisk.Submit(FeeBatch{FeeBps: 0, Intents: []PaymentIntent{
288			intent("p3", acct, asset, p3Amount),
289		}})
290		if err != nil {
291			t.Fatalf("submit p3: %v", err)
292		}
293		if r := p3.Results[0]; r.Status != StatusFunds || r.Record != nil {
294			t.Fatalf("real p3: %+v", r)
295		}
296		if bal, _ := fromDisk.Balance(acct, asset); bal != 10 {
297			t.Fatalf("balance after resubmits=%d want 10", bal)
298		}
299		final := mustQuery(t, fromDisk)
300		if !reflect.DeepEqual(final.Settlements, []Record{wantP1, wantP2}) {
301			t.Fatalf("final history:\n got %+v\nwant [p1,p2]", final.Settlements)
302		}
303	
304		// 再关句柄重开，确认磁盘文件与内存一致：p1 金额/扣款总额/序号、p2 全部原样，
305		// 没有任何预测成功记录或 p3，余额 10。
306		fromDisk.Close()
307		reopened := openOrFail(t, path)
308		diskFinal := mustQuery(t, reopened)
309		if !reflect.DeepEqual(diskFinal.Settlements, []Record{wantP1, wantP2}) {
310			t.Fatalf("reopened ledger history:\n got %+v\nwant [p1,p2]", diskFinal.Settlements)
311		}
312		if bal, _ := reopened.Balance(acct, asset); bal != 10 {
313			t.Fatalf("reopened balance=%d want 10", bal)
314		}
315	}
316	
317	// TestPreviewWaitsForInFlightBatchBothSettled：两笔真实付款都成功（余额剩 10）。
318	// 与批次并发发起的预览必须等批次完成：p1、p2 均 duplicate 并携带各自原结算
319	// 记录，p3=15 因余额 10 而 insufficient_balance。
320	func TestPreviewWaitsForInFlightBatchBothSettled(t *testing.T) {
321		runPreviewDuringSaveInterleave(t, false)
322	}
323	
324	// TestPreviewWaitsForInFlightBatchSecondSaveFails：p1 成功、p2 保存失败。
325	// 真实批次保留 p1、p2 报 storage_error、余额 40；并发预览基于该完整状态：
326	// p1 duplicate，p2 首次预计成功（序号 2），模拟余额 40→10 后 p3 余额不足；
327	// 失败的真实 p2 不被当成已结算，预览也不继承 storage_error。
328	func TestPreviewWaitsForInFlightBatchSecondSaveFails(t *testing.T) {
329		runPreviewDuringSaveInterleave(t, true)
330	}
