27	// 三笔原付款记录原样保留，磁盘账本与重新打开后的查询一致。全程只使用
28	// 既有公开接口与测试故障注入，可在本机离线稳定复现。
29	
30	func TestRefundStorageFailureIDReusedForDifferentPayment(t *testing.T) {
31		const initial int64 = 1_000_000
32		path := newTestLedger(t, []BalanceInit{{Account: "aa", Asset: "usdc", Balance: initial}})
33		l := openOrFail(t, path)
34	
35		// 三笔同账户、同资产的成功付款：扣款总额彼此不同，手续费均为非零并实际扣除。
36		// p1: 1000 + 100bps*1000(=10) = 1010
37		// p2: 1500 + 30bps*1500(=4)  = 1504
38		// p3: 2000 + 50bps*2000(=10) = 2010
39		setup := []struct {
40			id      string
41			amount  int64
42			bps     int
43			fee     int64
44			charged int64
45		}{
46			{"p1", 1000, 100, 10, 1010},
47			{"p2", 1500, 30, 4, 1504},
48			{"p3", 2000, 50, 10, 2010},
49		}
