55				t.Fatalf("setup settle %s: %+v", p.id, r)
56			}
57			if r.Record.Fee != p.fee || r.Record.Charged != p.charged {
58				t.Fatalf("setup %s fee/charged=%d/%d want %d/%d", p.id, r.Record.Fee, r.Record.Charged, p.fee, p.charged)
59			}
60			chargedTotal += p.charged
61			wantSettlements = append(wantSettlements, Record{
62				ID:        p.id,
63				Account:   "aa",
64				Paymaster: "pm",
65				Asset:     "usdc",
66				Amount:    p.amount,
67				Nonce:     1,
68				FeeBps:    p.bps,
69				Fee:       p.fee,
70				Charged:   p.charged,
71				Seq:       int64(i + 1),
72			})
73		}
