1	package payflow
2	
3	import (
4		"bytes"
5		"encoding/json"
6		"os"
7		"reflect"
8		"testing"
9	)
10	
11	// 本文件为 Preview 返回结果与真实账本之间的独立性提供回归保障。
12	// 预览结果中的预计成功项（settled）与重复项（duplicate）都会向调用者提供
13	// 结算记录（*Record），调用者可能为展示而修改这些编号、状态、说明与结算详情，
14	// 或调整结果列表。本文件围绕“返回数据被保留或修改后的行为”锁定：
15	//
16	//  1. 空间独立：同一批次内已结算付款的重复项、新付款的预计成功项、批内重复项
17	//     各自持有独立的结算详情；修改其中一项的账户、资产、付款方、金额、手续费、
18	//     扣款总额或成功序号，其他项仍保留原来的内容；调整列表顺序或替换其中一项，
19	//     也不能改变另一次调用取得的另一份预览。
20	//  2. 判定独立：修改预览中的历史结算详情后，查询仍看到原账户、原资产、原金额
21	//     与原序号，真实余额与账本文件保持不变；再次预览原请求仍返回 duplicate 和
22	//     真实原记录；用原编号提交合法但付款字段不同的请求仍返回 conflict。
23	//  3. 预计不落账：仅在预览中预计成功的新编号，即使调用者把它改成别的编号或把
24	//     扣款额改小，随后真实提交原请求仍按首次付款处理，实际扣款与手续费按请求
25	//     计算，不采用被修改的预览数据。
26	//  4. 时效语义：预览是“当时的结果”——后续真实付款或退款可以改变新查询与新
27	//     预览，但已经取得且未修改的旧结果不能跟着变化；原付款已退款时预览重复项
28	//     仍携带原结算详情，修改它不能改变退款历史或退回金额；余额不足的失败项
29	//     不带结算记录，修改它的状态不能让账本多出付款。
30	//
31	// 付款规则、预览参数、结算/退款功能与公开输出格式均不在本文件变更。
32	
33	// mustPreview 执行一次预览并返回结果；批次级错误直接失败。
34	func mustPreview(t *testing.T, l *Ledger, batch FeeBatch) *PreviewResult {
35		t.Helper()
36		res, err := l.Preview(batch)
37		if err != nil {
38			t.Fatalf("preview: %v", err)
39		}
40		return res
41	}
42	
43	// TestPreviewBatchItemsHoldIndependentRecords 锁定同一预览批次内各项结果的
44	// 独立性：批次同时含有已结算付款的重复项、新付款的预计成功项与该新编号的
45	// 批内重复项，三者各自携带独立的结算详情。逐项破坏性改写时，其余项保持原值；
46	// 调整列表顺序或替换其中一项，也不影响另一次调用取得的同内容预览。
47	func TestPreviewBatchItemsHoldIndependentRecords(t *testing.T) {
48		path := newTestLedger(t, []BalanceInit{
49			{Account: "aa", Asset: "usdc", Balance: 1_000_000},
50			{Account: "bb", Asset: "usdc", Balance: 500},
51		})
52		l := openOrFail(t, path)
53	
54		// 已真实结算的付款 p0：charged 1504，seq 1。
55		settled := mustSettle(t, l, 30, baseScenarioPayment("p0"))
56		wantP0 := baseScenarioRecord("p0", 1)
57		assertItemResult(t, settled, StatusSettled, "", wantP0)
58	
59		// 预览批次：已结算付款的重复项 + 新付款的预计成功项 + 新编号的批内重复项。
60		batch := FeeBatch{FeeBps: 30, Intents: []PaymentIntent{
61			baseScenarioPayment("p0"), // duplicate，携带真实原记录 seq 1
62			baseScenarioPayment("n1"), // settled，预计记录 seq 2
63			baseScenarioPayment("n1"), // duplicate，携带同一份预计记录的内容
64		}}
65		wantN1 := baseScenarioRecord("n1", 2)
66	
67		res := mustPreview(t, l, batch)
68		if !res.DryRun {
69			t.Fatalf("preview result must carry dry_run=true")
70		}
71		assertItemResult(t, res.Results[0], StatusDuplicate, reasonDuplicate, wantP0)
72		assertItemResult(t, res.Results[1], StatusSettled, "", wantN1)
73		assertItemResult(t, res.Results[2], StatusDuplicate, reasonDuplicate, wantN1)
74	
75		// 公开 JSON 格式回归：预览携带 dry_run 标记与完整结算详情，键名固定。
76		raw, err := json.Marshal(res)
77		if err != nil {
78			t.Fatal(err)
79		}
80		for _, frag := range []string{
81			`"dry_run":true`, `"id":"p0"`, `"status":"duplicate"`,
82			`"id":"n1"`, `"status":"settled"`,
83			`"account":"aa"`, `"paymaster":"pm-1"`, `"asset":"usdc"`,
84			`"amount":1500`, `"nonce":7`, `"fee_bps":30`, `"fee":4`,
85			`"charged":1504`, `"seq":1`, `"seq":2`,
86		} {
87			if !bytes.Contains(raw, []byte(frag)) {
88				t.Fatalf("preview result JSON missing %s:\n%s", frag, raw)
89			}
90		}
91	
92		// 三项必须是各自独立的记录分配。
93		if res.Results[0].Record == res.Results[1].Record ||
94			res.Results[0].Record == res.Results[2].Record ||
95			res.Results[1].Record == res.Results[2].Record {
96			t.Fatal("preview items in one batch share *Record allocations")
97		}
98	
99		// 不同次调用取得的结果内容相同，但也必须是独立分配、互不影响。
100		other := mustPreview(t, l, batch)
101		assertItemResult(t, other.Results[0], StatusDuplicate, reasonDuplicate, wantP0)
102		assertItemResult(t, other.Results[1], StatusSettled, "", wantN1)
103		assertItemResult(t, other.Results[2], StatusDuplicate, reasonDuplicate, wantN1)
104		for i := range res.Results {
105			if res.Results[i].Record == other.Results[i].Record {
106				t.Fatalf("item %d: results from separate preview calls share one *Record allocation", i)
107			}
108		}
109	
110		// 逐项破坏性改写第一份预览：每改一项，其余尚未被改的项与另一份预览的
111		// 所有项都必须保持原值。
112		wants := []Record{wantP0, wantN1, wantN1}
113		wantStatus := []string{StatusDuplicate, StatusSettled, StatusDuplicate}
114		corrupted := map[int]bool{}
115		for i := range res.Results {
116			corruptItemResult(&res.Results[i])
117			corrupted[i] = true
118			for j := range res.Results {
119				if corrupted[j] {
120					continue // 已被自己那次改写，不要求保持原值
121				}
122				if *res.Results[j].Record != wants[j] {
123					t.Fatalf("after corrupting item %d, item %d changed:\n got %+v\nwant %+v",
124						i, j, *res.Results[j].Record, wants[j])
125				}
126				if res.Results[j].Status != wantStatus[j] {
127					t.Fatalf("after corrupting item %d, item %d status=%s want %s",
128						i, j, res.Results[j].Status, wantStatus[j])
129				}
130			}
131			assertItemResult(t, other.Results[0], StatusDuplicate, reasonDuplicate, wantP0)
132			assertItemResult(t, other.Results[1], StatusSettled, "", wantN1)
133			assertItemResult(t, other.Results[2], StatusDuplicate, reasonDuplicate, wantN1)
134		}
135	
136		// 调整第一份预览的列表顺序、替换其中一项：另一份预览不受影响。
137		res.Results[0], res.Results[1] = res.Results[1], res.Results[0]
138		res.Results[2] = ItemResult{ID: "forged", Status: StatusSettled, Record: &Record{ID: "forged", Seq: 99}}
139		assertItemResult(t, other.Results[0], StatusDuplicate, reasonDuplicate, wantP0)
140		assertItemResult(t, other.Results[1], StatusSettled, "", wantN1)
141		assertItemResult(t, other.Results[2], StatusDuplicate, reasonDuplicate, wantN1)
142	
143		// 账本事实不受任何结果改写影响：仍只有 p0 一条记录，余额按真实扣款。
144		snap := mustQuery(t, l)
145		if !reflect.DeepEqual(snap.Settlements, []Record{wantP0}) {
146			t.Fatalf("ledger settlements after preview result edits:\n got %+v\nwant only %+v",
147				snap.Settlements, wantP0)
148		}
149		if bal, _ := l.Balance("aa", "usdc"); bal != 1_000_000-1504 {
150			t.Fatalf("balance changed after preview result edits: %d want %d", bal, 1_000_000-1504)
151		}
152		if bal, _ := l.Balance("bb", "usdc"); bal != 500 {
153			t.Fatalf("unrelated account balance changed: bb/usdc=%d want 500", bal)
154		}
155	}
156	
157	// TestPreviewDuplicateRecordEditsStayPrivate 锁定“修改预览中的历史结算详情”
158	// 不产生任何业务变更：查询仍看到原账户、原资产、原金额与原序号，真实余额与
159	// 账本文件内容保持不变；再次预览原请求仍返回 duplicate 和真实原记录；用原
160	// 编号提交合法但付款字段不同的请求仍返回 conflict。
161	func TestPreviewDuplicateRecordEditsStayPrivate(t *testing.T) {
162		path := newTestLedger(t, []BalanceInit{
163			{Account: "aa", Asset: "usdc", Balance: 2000},
164			{Account: "bb", Asset: "usdc", Balance: 800},
165		})
166		l := openOrFail(t, path)
167	
168		// 真实付款 p1：1500 本金 + 30bps 手续费 4，共扣 1504，aa/usdc 余 496。
169		mustSettle(t, l, 30, baseScenarioPayment("p1"))
170		wantP1 := baseScenarioRecord("p1", 1)
171	
172		// 预览原请求：duplicate，携带账本中的历史结算详情。
173		res := mustPreview(t, l, FeeBatch{FeeBps: 30, Intents: []PaymentIntent{baseScenarioPayment("p1")}})
174		assertItemResult(t, res.Results[0], StatusDuplicate, reasonDuplicate, wantP1)
175	
176		// 记录调用者改写之前的账本文件字节：单纯修改预览结果不能改写账本文件。
177		fileBefore, err := os.ReadFile(path)
178		if err != nil {
179			t.Fatal(err)
180		}
181	
182		// 调用者破坏性改写预览里的历史结算详情（金额改小、去向改成 zz/btc、
183		// 序号改成 77）。
184		corruptItemResult(&res.Results[0])
185	
186		// 1. 查询仍看到原账户、原资产、原金额与原序号；只有一条结算记录。
187		snap := mustQuery(t, l)
188		if !reflect.DeepEqual(snap.Settlements, []Record{wantP1}) {
189			t.Fatalf("real settlement altered by preview edit:\n got %+v\nwant %+v",
190				snap.Settlements, wantP1)
191		}
192	
193		// 2. 真实余额仍是 496：改小预览里的金额不能把钱补回来。
194		if bal, _ := l.Balance("aa", "usdc"); bal != 496 {
195			t.Fatalf("balance changed after editing preview result: %d want 496", bal)
196		}
197		if bal, _ := l.Balance("zz", "btc"); bal != 0 {
198			t.Fatalf("payment leaked to forged destination: zz/btc=%d want 0", bal)
199		}
200	
201		// 3. 账本文件字节不变。
202		fileAfter, err := os.ReadFile(path)
203		if err != nil {
204			t.Fatal(err)
205		}
206		if !bytes.Equal(fileBefore, fileAfter) {
207			t.Fatalf("ledger file changed by editing a preview result")
208		}
209	
210		// 4. 再次预览原请求：仍 duplicate，携带真实原记录（不是被改写的内容），
211		//    且是独立分配。
212		res2 := mustPreview(t, l, FeeBatch{FeeBps: 30, Intents: []PaymentIntent{baseScenarioPayment("p1")}})
213		assertItemResult(t, res2.Results[0], StatusDuplicate, reasonDuplicate, wantP1)
214		if res2.Results[0].Record == res.Results[0].Record {
215			t.Fatal("fresh preview shares allocation with a corrupted held result")
216		}
217	
218		// 5. 用原编号提交合法但付款字段不同的请求：仍 conflict，不新增记录、不扣款。
219		mutations := []struct {
220			name string
221			mut  func(*PaymentIntent, *int)
222		}{
223			{"amount", func(it *PaymentIntent, _ *int) { *it.Amount = 1501 }},
224			{"nonce", func(it *PaymentIntent, _ *int) { it.Nonce = 8 }},
225			{"paymaster", func(it *PaymentIntent, _ *int) { it.Paymaster = "pm-2" }},
226			{"account", func(it *PaymentIntent, _ *int) { it.Account = "bb" }},
227			{"fee_bps", func(_ *PaymentIntent, bps *int) { *bps = 31 }},
228		}
229		for _, tc := range mutations {
230			it := baseScenarioPayment("p1")
231			bps := 30
232			tc.mut(&it, &bps)
233			got := mustSettle(t, l, bps, it)
234			if got.Status != StatusConflict || got.Record != nil {
235				t.Fatalf("mutation %s want conflict without record, got %+v", tc.name, got)
236			}
237		}
238		if len(mustQuery(t, l).Settlements) != 1 {
239			t.Fatalf("conflicts must not add settlement records")
240		}
241		if bal, _ := l.Balance("aa", "usdc"); bal != 496 {
242			t.Fatalf("conflicts changed balance: %d want 496", bal)
243		}
244	}
245	
246	// TestPreviewPredictedSuccessEditsDoNotLeaIntoRealSubmit 锁定“预计成功只存在于
247	// 预览里”：调用者把预计成功项改成别的编号、把扣款额改小之后，真实提交原请求
248	// 仍按首次付款处理，实际扣款与手续费按请求计算，不采用被修改的预览数据；
249	// 被伪造的编号也不会因此被占用。
250	func TestPreviewPredictedSuccessEditsDoNotLeaIntoRealSubmit(t *testing.T) {
251		path := newTestLedger(t, []BalanceInit{{Account: "aa", Asset: "usdc", Balance: 2000}})
252		l := openOrFail(t, path)
253	
254		// 新编号 n1 仅在预览中预计成功：charged 1504，预计序号 1。
255		res := mustPreview(t, l, FeeBatch{FeeBps: 30, Intents: []PaymentIntent{baseScenarioPayment("n1")}})
256		wantN1 := baseScenarioRecord("n1", 1)
257		assertItemResult(t, res.Results[0], StatusSettled, "", wantN1)
258	
259		// 调用者把预计成功项改成别的编号（HACK-ID/HACK-REC）、把扣款额改小（99）。
260		corruptItemResult(&res.Results[0])
261	
262		// 真实提交原请求：仍按首次付款处理（不是 duplicate/conflict），扣款与
263		// 手续费按请求计算（1504，含手续费 4），序号从 1 开始，不采用被修改的
264		// 预览数据。
265		got := mustSettle(t, l, 30, baseScenarioPayment("n1"))
266		assertItemResult(t, got, StatusSettled, "", wantN1)
267		if bal, _ := l.Balance("aa", "usdc"); bal != 496 {
268			t.Fatalf("real submit must charge by the request: bal=%d want 496", bal)
269		}
270	
271		// 被伪造进预览结果的编号没有因此被占用：以该编号真实付款仍按首次处理。
272		forged := mustSettle(t, l, 0, intent("HACK-REC", "aa", "usdc", 10))
273		if forged.Status != StatusSettled || forged.Record == nil || forged.Record.Seq != 2 {
274			t.Fatalf("forged id must not be occupied by an edited preview result: %+v", forged)
275		}
276		if bal, _ := l.Balance("aa", "usdc"); bal != 486 {
277			t.Fatalf("balance after forged-id payment=%d want 486", bal)
278		}
279	
280		// 账本视角：两条真实记录按成功先后排列，没有任何预测数据混入。
281		snap := mustQuery(t, l)
282		wantForged := Record{
283			ID: "HACK-REC", Account: "aa", Paymaster: "pm", Asset: "usdc",
284			Amount: 10, Nonce: 1, FeeBps: 0, Fee: 0, Charged: 10, Seq: 2,
285		}
286		if !reflect.DeepEqual(snap.Settlements, []Record{wantN1, wantForged}) {
287			t.Fatalf("ledger settlements:\n got %+v\nwant %+v / %+v",
288				snap.Settlements, wantN1, wantForged)
289		}
290	}
291	
292	// TestPreviewHeldResultKeepsPointInTimeMeaning 锁定预览的时效语义：预览是
293	// “当时的结果”。后续真实付款或退款可以改变新查询与新预览，但已经取得且
294	// 未修改的旧预览结果不能跟着变化。
295	func TestPreviewHeldResultKeepsPointInTimeMeaning(t *testing.T) {
296		path := newTestLedger(t, []BalanceInit{{Account: "aa", Asset: "usdc", Balance: 5000}})
297		l := openOrFail(t, path)
298	
299		// 真实付款 p1：charged 1504，seq 1，余 3496。
300		mustSettle(t, l, 30, baseScenarioPayment("p1"))
301		wantP1 := baseScenarioRecord("p1", 1)
302	
303		// 当时预览：p1 duplicate（携带原记录），新编号 n1 预计成功（seq 2）。
304		batch := FeeBatch{FeeBps: 30, Intents: []PaymentIntent{
305			baseScenarioPayment("p1"),
306			baseScenarioPayment("n1"),
307		}}
308		held := mustPreview(t, l, batch)
309		wantN1 := baseScenarioRecord("n1", 2)
310		assertItemResult(t, held.Results[0], StatusDuplicate, reasonDuplicate, wantP1)
311		assertItemResult(t, held.Results[1], StatusSettled, "", wantN1)
312	
313		// 后续真实付款与退款改变账本：n1 真实落账（seq 2），p1 全额退款。
314		realN1 := mustSettle(t, l, 30, baseScenarioPayment("n1"))
315		assertItemResult(t, realN1, StatusSettled, "", wantN1)
316		ref := mustRefundOne(t, l, "r1", "p1", "full refund")
317		wantR1 := RefundRecord{
318			ID: "r1", SettlementID: "p1", Reason: "full refund",
319			Account: "aa", Asset: "usdc", Amount: 1500, Fee: 4, Charged: 1504,
320			AfterSeq: 2, Seq: 1,
321		}
322		assertRefundResultRecord(t, ref, StatusRefundSuccess, wantR1)
323	
324		// 新查询反映新账本：两条结算、一条退款，余额 5000-1504-1504+1504=3496。
325		snap := mustQuery(t, l)
326		if !reflect.DeepEqual(snap.Settlements, []Record{wantP1, wantN1}) {
327			t.Fatalf("settlements after real changes:\n got %+v", snap.Settlements)
328		}
329		if !reflect.DeepEqual(snap.Refunds, []RefundRecord{wantR1}) {
330			t.Fatalf("refunds after real changes:\n got %+v", snap.Refunds)
331		}
332		if bal, _ := l.Balance("aa", "usdc"); bal != 3496 {
333			t.Fatalf("balance after real changes=%d want 3496", bal)
334		}
335	
336		// 新预览反映新账本：p1 已退款仍 duplicate 携带原记录；n1 现在已是
337		// 真实结算，相同请求变成 duplicate 而不再是预计成功。
338		fresh := mustPreview(t, l, batch)
339		assertItemResult(t, fresh.Results[0], StatusDuplicate, reasonDuplicate, wantP1)
340		assertItemResult(t, fresh.Results[1], StatusDuplicate, reasonDuplicate, wantN1)
341	
342		// 但已经取得且未修改的旧预览不能跟着变化：n1 一项仍是当时的“预计成功”，
343		// p1 一项仍携带当时的原记录。
344		if !held.DryRun {
345			t.Fatalf("held preview lost its dry_run marker")
346		}
347		assertItemResult(t, held.Results[0], StatusDuplicate, reasonDuplicate, wantP1)
348		assertItemResult(t, held.Results[1], StatusSettled, "", wantN1)
349	}
350	
351	// TestPreviewRefundedOriginalDuplicateEditsStayPrivate 锁定“原付款已退款”
352	// 场景：预览重复项仍携带原结算详情；修改它不能改变退款历史或退回金额，
353	// 再次预览仍返回真实原记录。
354	func TestPreviewRefundedOriginalDuplicateEditsStayPrivate(t *testing.T) {
355		path := newTestLedger(t, []BalanceInit{{Account: "aa", Asset: "usdc", Balance: 2000}})
356		l := openOrFail(t, path)
357	
358		mustSettle(t, l, 30, baseScenarioPayment("p1"))
359		wantP1 := baseScenarioRecord("p1", 1)
360		ref := mustRefundOne(t, l, "r1", "p1", "full refund")
361		wantR1 := RefundRecord{
362			ID: "r1", SettlementID: "p1", Reason: "full refund",
363			Account: "aa", Asset: "usdc", Amount: 1500, Fee: 4, Charged: 1504,
364			AfterSeq: 1, Seq: 1,
365		}
366		assertRefundResultRecord(t, ref, StatusRefundSuccess, wantR1)
367		if bal, _ := l.Balance("aa", "usdc"); bal != 2000 {
368			t.Fatalf("balance after refund=%d want 2000", bal)
369		}
370	
371		// 原付款已退款：预览重复项仍携带原结算详情（原序号 1、原扣款 1504）。
372		res := mustPreview(t, l, FeeBatch{FeeBps: 30, Intents: []PaymentIntent{baseScenarioPayment("p1")}})
373		assertItemResult(t, res.Results[0], StatusDuplicate, reasonDuplicate, wantP1)
374	
375		fileBefore, err := os.ReadFile(path)
376		if err != nil {
377			t.Fatal(err)
378		}
379	
380		// 修改预览中的历史结算详情（金额改小、去向改成 zz/btc、序号改成 77）。
381		corruptItemResult(&res.Results[0])
382	
383		// 退款历史与退回金额不变，原结算记录不变，余额不变，账本文件不变。
384		snap := mustQuery(t, l)
385		if !reflect.DeepEqual(snap.Refunds, []RefundRecord{wantR1}) {
386			t.Fatalf("refund history altered by preview edit:\n got %+v\nwant %+v",
387				snap.Refunds, wantR1)
388		}
389		if !reflect.DeepEqual(snap.Settlements, []Record{wantP1}) {
390			t.Fatalf("settlement altered by preview edit:\n got %+v\nwant %+v",
391				snap.Settlements, wantP1)
392		}
393		if bal, _ := l.Balance("aa", "usdc"); bal != 2000 {
394			t.Fatalf("refunded amount changed after preview edit: bal=%d want 2000", bal)
395		}
396		if bal, _ := l.Balance("zz", "btc"); bal != 0 {
397			t.Fatalf("refund leaked to forged destination: zz/btc=%d want 0", bal)
398		}
399		fileAfter, err := os.ReadFile(path)
400		if err != nil {
401			t.Fatal(err)
402		}
403		if !bytes.Equal(fileBefore, fileAfter) {
404			t.Fatalf("ledger file changed by editing a preview result")
405		}
406	
407		// 再次预览原请求：仍 duplicate，携带真实原记录，且是独立分配。
408		res2 := mustPreview(t, l, FeeBatch{FeeBps: 30, Intents: []PaymentIntent{baseScenarioPayment("p1")}})
409		assertItemResult(t, res2.Results[0], StatusDuplicate, reasonDuplicate, wantP1)
410		if res2.Results[0].Record == res.Results[0].Record {
411			t.Fatal("fresh preview shares allocation with a corrupted held result")
412		}
413	}
414	
415	// TestPreviewFailedItemEditsAddNoPayment 锁定失败项的隔离：余额不足的预览
416	// 失败项不携带结算记录；调用者即使把它的状态改成“成功”并伪造一条结算
417	// 记录，账本也不能因此多出付款，真实提交原请求仍按真实余额判定。
418	func TestPreviewFailedItemEditsAddNoPayment(t *testing.T) {
419		path := newTestLedger(t, []BalanceInit{{Account: "aa", Asset: "usdc", Balance: 100}})
420		l := openOrFail(t, path)
421	
422		// 余额不足的失败项：insufficient_balance，不带结算记录。
423		res := mustPreview(t, l, FeeBatch{FeeBps: 0, Intents: []PaymentIntent{intent("big", "aa", "usdc", 500)}})
424		if r := res.Results[0]; r.Status != StatusFunds || r.Record != nil {
425			t.Fatalf("failed preview item must not carry a record: %+v", r)
426		}
427	
428		fileBefore, err := os.ReadFile(path)
429		if err != nil {
430			t.Fatal(err)
431		}
432	
433		// 调用者把失败项伪造成“成功”：改状态、清空说明、附上一段伪造的结算记录。
434		res.Results[0].Status = StatusSettled
435		res.Results[0].Reason = ""
436		res.Results[0].Record = &Record{
437			ID: "big", Account: "aa", Paymaster: "pm", Asset: "usdc",
438			Amount: 500, Nonce: 1, FeeBps: 0, Fee: 0, Charged: 500, Seq: 1,
439		}
440	
441		// 账本不能因此多出付款：无结算记录、余额不变、账本文件不变。
442		snap := mustQuery(t, l)
443		if len(snap.Settlements) != 0 {
444			t.Fatalf("forged preview item added a settlement: %+v", snap.Settlements)
445		}
446		if bal, _ := l.Balance("aa", "usdc"); bal != 100 {
447			t.Fatalf("balance changed by forging a preview item: %d want 100", bal)
448		}
449		fileAfter, err := os.ReadFile(path)
450		if err != nil {
451			t.Fatal(err)
452		}
453		if !bytes.Equal(fileBefore, fileAfter) {
454			t.Fatalf("ledger file changed by editing a preview result")
455		}
456	
457		// 真实提交原请求仍按真实余额判定：余额不足，且失败不留记录。
458		got := mustSettle(t, l, 0, intent("big", "aa", "usdc", 500))
459		if got.Status != StatusFunds || got.Record != nil {
460			t.Fatalf("real submit must follow the real balance, got %+v", got)
461		}
462		if len(mustQuery(t, l).Settlements) != 0 {
463			t.Fatalf("a failed payment must not add a settlement")
464		}
465		if bal, _ := l.Balance("aa", "usdc"); bal != 100 {
466			t.Fatalf("failed payment changed balance: %d want 100", bal)
467		}
468	}
